"""Finalize v1 manifest and ZIP; only cleans generated bytecode inside release/v1."""
from pathlib import Path
import hashlib
import json
import zipfile
import argparse

ROOT=Path(__file__).resolve().parents[2]
parser=argparse.ArgumentParser()
parser.add_argument('--version',choices=['v1','v2'],default='v1')
version=parser.parse_args().version
release=(ROOT/'release'/version).resolve()
assert release.is_relative_to(ROOT/'release') and release.name==version
print('Collecting files',flush=True)
paths=list(release.rglob('*'))
print('Found',len(paths),'entries',flush=True)
for p in paths:
    if p.is_file() and p.suffix=='.pyc':
        assert p.resolve().is_relative_to(release)
        p.unlink()
print('Bytecode cleanup complete',flush=True)
assert not (release/'data').exists()
assert not any(p.name in {'torch','faster_whisper','ctranslate2','av'} for p in (release/'runtime/Lib/site-packages').iterdir())
files=sorted(p for p in release.rglob('*') if p.is_file() and p.name!='SHA256SUMS.json')
manifest={}
for i,p in enumerate(files):
    manifest[p.relative_to(release).as_posix()]=hashlib.sha256(p.read_bytes()).hexdigest()
    if i%1000==0:print('Hashed',i,'/',len(files),flush=True)
(release/'SHA256SUMS.json').write_text(json.dumps(manifest,indent=2),encoding='utf-8')
archive=ROOT/'release'/f'{version}.zip'
print('Creating ZIP',flush=True)
with zipfile.ZipFile(archive,'w',compression=zipfile.ZIP_DEFLATED,compresslevel=6) as z:
    for i,p in enumerate(files+[release/'SHA256SUMS.json']):
        z.write(p,p.relative_to(ROOT/'release').as_posix())
        if i%1000==0:print('Archived',i,flush=True)
print('Checking ZIP CRC',flush=True)
with zipfile.ZipFile(archive) as z:
    bad=z.testzip();assert bad is None,bad
summary=dict(files=len(manifest)+1,uncompressed_mib=sum(p.stat().st_size for p in files)/2**20,
             zip_mib=archive.stat().st_size/2**20,zip_sha256=hashlib.sha256(archive.read_bytes()).hexdigest())
(ROOT/'release'/f'{version}.zip.sha256').write_text(summary['zip_sha256']+f'  {version}.zip\n',encoding='ascii')
(ROOT/'.tmp'/f'release-{version}-summary.json').write_text(json.dumps(summary,indent=2),encoding='utf-8')
print(json.dumps(summary),flush=True)
